      c.textContent=ok?'Copied':'Press Ctrl+C';
      setTimeout(function(){c.textContent='Copy these'},1400); return;
    }
    var t=e.target.closest('[data-t]');
    if(t){ off[t.dataset.t]=!off[t.dataset.t]; render(); }
